export function statesFor(route) {
  const states = [['normal', 'Обычное']]
  if (['vault', 'files'].includes(route)) states.push(['empty', 'Пустое'])
  if (['vault', 'files', 'document'].includes(route)) states.push(['loading', 'Загрузка'])
  if (['vault', 'files', 'document', 'edit', 'note', 'unlock', 'setup'].includes(route))
    states.push(['error', 'Ошибка'])
  if (!['welcome', 'setup', 'unlock'].includes(route))
    states.push(['readonly', 'Только чтение'], ['locked', 'Закрыто'])
  return states
}
